class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # Initialize adjacency list with initial roads (i -> i+1)
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append(i + 1)

        result = []

        # Process each query
        for u, v in queries:
            # Add the new road from u to v
            graph[u].append(v)

            # Find shortest path from 0 to n-1 using BFS
            # Since all edges have weight 1, BFS gives us shortest path
            visited = [False] * n
            queue = [(0, 0)]  # (city, distance)
            visited[0] = True

            while queue:
                city, dist = queue.pop(0)

                if city == n - 1:
                    result.append(dist)
                    break

                for neighbor in graph[city]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append((neighbor, dist + 1))

        return result

class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0) in grid coordinates
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert (row, col) coordinates to linear position
        # position = row * n + col
        return row * n + col

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed for all rows to be palindromic
        row_flips = 0
        for i in range(m):
            # For each row, check symmetric pairs
            for j in range(n // 2):
                # Compare position j with position n-1-j
                if grid[i][j] != grid[i][n - 1 - j]:
                    row_flips += 1

        # Calculate flips needed for all columns to be palindromic
        col_flips = 0
        for j in range(n):
            # For each column, check symmetric pairs
            for i in range(m // 2):
                # Compare position i with position m-1-i
                if grid[i][j] != grid[m - 1 - i][j]:
                    col_flips += 1

        # Return minimum of row flips or column flips
        return min(row_flips, col_flips)

